Lemma dus_loop2 : forall L (cur kti kid kname K : Z)
    ra sp gp tp t0 t1 t2 s0 a0 a1 a3 a4 a5 a6 a7 s4 s5 s6 s8 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
